const idData = $json;
const refundData = $('Calculate Refund Eligibility1').first().json;

if (!idData.next_id) throw new Error('Step 5 did not return next_id.');
if (!refundData.order_id || !refundData.request_type) {
  throw new Error('Order ID and request type are required to log a refund request.');
}

const requestType = String(refundData.request_type || '').trim().toLowerCase();
const orderAmount = Number(refundData.amount ?? 0);
const shippingFee = Number(refundData.shipping_fee ?? 0);
const returnRefundAmount = Number(refundData.return_refund_amount ?? 0);
const paymentMethod = String(refundData.payment_method || '').trim().toLowerCase();

// For test logging, calculate the requested amount independently of eligibility.
// This records the request value but does not execute a payment/refund.
let calculatedAmount;
if (requestType === 'return_refund') {
  calculatedAmount = returnRefundAmount;
} else if (requestType === 'cancel' && paymentMethod === 'cod') {
  calculatedAmount = 0;
} else if (['damaged', 'wrong_item', 'delayed', 'lost', 'return', 'cancel'].includes(requestType)) {
  calculatedAmount = orderAmount + shippingFee;
} else {
  calculatedAmount = Number(refundData.refund_amount ?? orderAmount + shippingFee);
}
if (!Number.isFinite(calculatedAmount) || calculatedAmount < 0) calculatedAmount = 0;

const decision = String(refundData.decision || 'decline').toLowerCase();
const route = String(refundData.route || 'decline').toLowerCase();
const confirmed = refundData.confirmed === true || String(refundData.confirmed).toLowerCase() === 'true';
let status;
if (decision === 'eligible' && !confirmed) {
  status = 'pending_confirmation';
} else if (decision === 'eligible' && requestType === 'return_refund' && (String(refundData.inspection_status || '').toLowerCase() !== 'passed' || String(refundData.return_status || '').toLowerCase() !== 'inspected')) {
  status = 'pending_inspection';
} else if (decision === 'eligible' && route !== 'auto' && requestType !== 'return_refund') {
  status = 'pending_approval';
} else if (decision === 'eligible' && confirmed && (route === 'auto' || requestType === 'return_refund')) {
  status = requestType === 'return_refund' ? 'initiated' : 'completed';
} else if (decision === 'human' || route === 'human') {
  status = 'pending_review';
} else if (decision === 'need_evidence' || route === 'need_evidence') {
  status = 'pending_evidence';
} else {
  status = 'rejected';
}

return {
  json: {
    ...refundData,
    refund_id: String(idData.next_id),
    return_id: refundData.latest_return_id ?? null,
    amount: calculatedAmount,
    refund_amount: calculatedAmount,
    currency: refundData.return_currency || refundData.currency,
    method: String(refundData.payment_method || '').toLowerCase() === 'cod' ? 'bank_upi' : 'original_payment',
    status,
    approved_by: refundData.approved_by ?? '',
    decision_reason: String(refundData.reasons || 'No eligibility reason provided')
  }
};

// Step 2 — Calculate refund amount and check eligibility.
// Reads the current input item containing request and Databricks fields.
// This node only evaluates eligibility; it does not write to databases.

const request = $('Normalize Refund Input1').first().json;
const dbData = $input.first()?.json || {};
const input = { ...request, ...dbData };

const rt = String(input.request_type || '').trim().toLowerCase();
const risk = Number(input.risk_score ?? 0);
const refunds90 = Number(input.refunds_last_90d ?? 0);
const custTier = String(input.tier || '').trim().toLowerCase();

const unused =
  input.item_unused === true ||
  String(input.item_unused).toLowerCase() === 'true';

const evidence =
  input.evidence_ok === true ||
  String(input.evidence_ok).toLowerCase() === 'true';

const exception =
  input.wants_exception === true ||
  String(input.wants_exception).toLowerCase() === 'true';

const newCountry = String(input.new_country || '')
  .trim()
  .toUpperCase();

const orderStatus = String(input.order_status || '').toLowerCase();
const shipStatus = String(input.ship_status || '').toLowerCase();
const claimStatus = String(input.claim_status || '').toLowerCase();
const returnStatus = String(input.return_status || '').toLowerCase();
const inspectionStatus = String(input.inspection_status || '').toLowerCase();
const returnResolution = String(input.latest_return_resolution || '').toLowerCase();

const refunded = String(input.refunded || '').toLowerCase();
const hasExistingRefund =
  String(input.has_existing_refund).toLowerCase() === 'true';

const refundCount = Number(input.refund_count || 0);
const returnCount = Number(input.return_count || 0);

const build = (
  decision,
  route,
  resultTier,
  reasons,
  amount = 0,
  daysLeft = 0
) => ({
  ...input,
  decision,
  route,
  tier: resultTier,
  refund_amount: Number(amount || 0),
  currency: String(input.return_currency || input.currency || ''),
  days_remaining: Number(daysLeft || 0),
  reasons: Array.isArray(reasons) ? reasons.join('; ') : String(reasons),
  policy_version: String(input.policy_version || '')
});

const decline = (message, days = 0) =>
  build('decline', 'decline', 'T0', message, 0, days);

const human = (message, days = 0) =>
  build('human', 'human', 'T3', message, 0, days);

const byAmount = (refund, reasons, days) => {
  const autoLimit = Number(input.auto_limit || 0);
  const approvalLimit = Number(input.approval_limit || 0);
  const autoActions = Number(input.auto_actions_30d || 0);
  const maxAutoActions = Number(input.max_auto_actions_30d || 0);

  if (refund <= autoLimit) {
    if (autoActions >= maxAutoActions) {
      return build(
        'eligible',
        'approval',
        'T2',
        [...reasons, 'Auto-action limit reached'],
        refund,
        days
      );
    }

    return build('eligible', 'auto', 'T1', reasons, refund, days);
  }

  if (refund <= approvalLimit) {
    return build('eligible', 'approval', 'T2', reasons, refund, days);
  }

  return human(
    [...reasons, 'Refund exceeds approval limit'],
    days
  );
};

let result;

if (!input.order_id) {
  result = decline('Order not found for this customer');

} else if (!rt) {
  result = decline(
    'Missing request_type: ensure the incoming payload is passed to this node'
  );

} else {
  const amount = Number(input.amount || 0);
  const fee = Number(input.shipping_fee || 0);

  if (
    rt !== 'address_change' &&
    (
      refunded === 'yes' ||
      hasExistingRefund ||
      refundCount > 0
    )
  ) {
    result = decline('Already refunded');

  } else if (
    rt !== 'address_change' &&
    rt !== 'return_refund' &&
    returnCount > 0
  ) {
    result = decline('A return is already in progress for this order');

  } else if (orderStatus === 'cancelled') {
    result = decline('Order is already cancelled');

  } else if (
    risk >= Number(input.risk_score_escalate || 70) ||
    refunds90 >= Number(input.serial_refund_threshold || 3)
  ) {
    result = human('Risk gate: customer needs human review');

  } else if (rt === 'return') {
    if (orderStatus !== 'delivered') {
      result = decline('Order not delivered yet');

    } else {
      const days = Number(input.days_since_delivery || 0);
      const left = Number(input.return_window_days || 0) - days;

      if (left < 0) {
        result = (exception || custTier === 'vip')
          ? human(
              `Outside the ${input.return_window_days}-day window; exception request`,
              left
            )
          : decline(
              `Delivered ${days} days ago; return window is ${input.return_window_days} days`,
              left
            );

      } else if (!unused) {
        result = decline('Item must be unused', left);

      } else {
        result = byAmount(amount, ['Return'], left);
      }
    }

  } else if (rt === 'return_refund') {
    if (returnCount === 0 || !input.latest_return_id) {
      result = decline('No return found for this order; create the return first');

    } else if (
      returnStatus !== 'inspected' ||
      inspectionStatus !== 'passed'
    ) {
      result = decline(
        `The return is ${returnStatus || 'unknown'} and inspection has not passed`
      );

    } else if (returnResolution === 'exchange') {
      result = decline('The latest return resolution is exchange, not refund');

    } else {
      result = byAmount(
        Number(input.return_refund_amount || 0),
        ['Refund for the returned item'],
        0
      );
    }

  } else if (rt === 'damaged' || rt === 'wrong_item') {
    if (orderStatus !== 'delivered') {
      result = decline('Order not delivered yet');

    } else if (
      Number(input.days_since_delivery || 0) >
      Number(input.damage_report_days || 7)
    ) {
      result = human(
        `Reported ${input.days_since_delivery} days after delivery; limit is ${input.damage_report_days} days`
      );

    } else if (!evidence) {
      result = build(
        'need_evidence',
        'need_evidence',
        'T0',
        'Need a specific description or photo of the problem',
        0,
        0
      );

    } else {
      result = byAmount(
        amount + fee,
        [`${rt} refund including shipping`],
        0
      );
    }

  } else if (rt === 'delayed') {
    const late = Number(input.days_late || 0);

    if (late <= Number(input.delay_threshold_days || 0)) {
      result = decline(
        `${late} days late; threshold is ${input.delay_threshold_days}. Share the ETA`
      );

    } else {
      result = byAmount(amount + fee, [`Delayed ${late} days`], 0);
    }

  } else if (rt === 'lost') {
    if (shipStatus !== 'lost') {
      result = decline('Carrier has not marked it lost');

    } else {
      result = byAmount(amount + fee, ['Lost in transit'], 0);
    }

  } else if (rt === 'not_received') {
    if (shipStatus !== 'delivered') {
      result = decline('Carrier does not show it delivered; use tracking');

    } else if (claimStatus === 'raised') {
      result = decline('A carrier claim is already open');

    } else {
      result = build(
        'eligible',
        'auto',
        'T1',
        'Raise a carrier claim; follow up within 48 hours; no instant refund',
        0,
        0
      );
    }

  } else if (rt === 'cancel') {
    if (!['payment_pending', 'packed'].includes(orderStatus)) {
      result = decline('Already shipped or delivered');

    } else {
      result = byAmount(
        String(input.payment_method || '').toLowerCase() === 'cod'
          ? 0
          : amount + fee,
        ['Cancellation'],
        0
      );
    }

  } else if (rt === 'address_change') {
    const country = String(input.country || '').toUpperCase();

    if (newCountry && newCountry !== country) {
      result = human('Address in a different country needs human review');

    } else if (['payment_pending', 'packed'].includes(orderStatus)) {
      result = build(
        'eligible',
        'auto',
        'T1',
        'Not dispatched yet; address can be changed now',
        0,
        0
      );

    } else if (orderStatus === 'shipped') {
      result = build(
        'eligible',
        'approval',
        'T2',
        'Already shipped; needs a carrier intercept request. Fee may apply and it is not guaranteed',
        0,
        0
      );

    } else {
      result = decline(
        `Order is ${orderStatus || 'unknown'}; address cannot be changed`
      );
    }

  } else {
    result = decline(`Unknown request type: ${rt}`);
  }
}

return [{ json: result }];

