  decision: data.decision ?? 'decline',
  route: data.route ?? 'decline',
  amount: data.amount ?? 0,
  already_done: /already refunded/i.test(declinedReason),
  message: inserted
    ? (String(data.decision || '').toLowerCase() === 'eligible' && String(data.confirmed).toLowerCase() === 'true'
        ? 'Refund request was logged. Order status was not changed because the order update did not complete.'
        : declinedReason)
    : 'Refund request could not be confirmed as inserted; order status was not changed.'
} };

const data = $node['Merge Refund Inputs with Generated ID'].json || {};
const update = $node['Step 8 - Update Order Status'].json || {};
return { json: { success: true, refund_created: true, order_updated: true, refund_id: data.refund_id ?? null, order_id: data.order_id ?? null, status: data.status ?? null, amount: data.amount ?? 0, message: 'Refund record inserted and order status updated successfully. Continue to Salesforce actions.' } };

